# HobTools for Hob - installer / uninstaller (run through Install HobTools.bat or Uninstall HobTools.bat)
param([switch]$Uninstall, [string]$GameDir, [string]$LogFile)
$ErrorActionPreference = 'Stop'
if ($LogFile) { try { Start-Transcript -Path $LogFile -Force | Out-Null } catch {} }
$Version = '0.9 beta'
$Here = $PSScriptRoot
function Say($t, $c = 'Gray') { Write-Host $t -ForegroundColor $c }
function Fail($t) { Say $t 'Red'; Say ''; Say 'Nothing was changed.' 'Yellow'; exit 1 }

Say "HobTools $Version - $(if ($Uninstall) {'uninstall'} else {'install'})" 'Cyan'
Say ''
if (Get-Process -Name 'HOB' -ErrorAction SilentlyContinue) { Fail 'Hob is running. Close the game first, then run this again.' }

# ---------- find the game folder ----------
function Find-Hob {
  $cands = New-Object System.Collections.Generic.List[string]
  foreach ($p in @((Split-Path $Here -Parent), $Here)) { if ($p) { $cands.Add($p) } }
  # Epic Games Launcher manifests
  $man = Join-Path $env:ProgramData 'Epic\EpicGamesLauncher\Data\Manifests'
  if (Test-Path $man) { Get-ChildItem $man -Filter *.item -ErrorAction SilentlyContinue | ForEach-Object {
      try { $j = Get-Content $_.FullName -Raw | ConvertFrom-Json; if ($j.DisplayName -eq 'Hob' -and $j.InstallLocation) { $cands.Add($j.InstallLocation) } } catch {} } }
  # Steam libraries
  foreach ($k in 'HKLM:\SOFTWARE\WOW6432Node\Valve\Steam','HKLM:\SOFTWARE\Valve\Steam','HKCU:\SOFTWARE\Valve\Steam') {
    try { $sp = (Get-ItemProperty $k -ErrorAction Stop).InstallPath; if (-not $sp) { $sp = (Get-ItemProperty $k).SteamPath } } catch { $sp = $null }
    if ($sp) { $cands.Add("$sp\steamapps\common\Hob")
      $vdf = "$sp\steamapps\libraryfolders.vdf"
      if (Test-Path $vdf) { foreach ($m in [regex]::Matches((Get-Content $vdf -Raw), '"path"\s+"([^"]+)"')) { $cands.Add(($m.Groups[1].Value -replace '\\\\','\') + '\steamapps\common\Hob') } } } }
  # GOG
  foreach ($k in 'HKLM:\SOFTWARE\WOW6432Node\GOG.com\Games','HKLM:\SOFTWARE\GOG.com\Games') {
    if (Test-Path $k) { Get-ChildItem $k | ForEach-Object { try { $g = Get-ItemProperty $_.PSPath; if ($g.gameName -like 'Hob*' -and $g.path) { $cands.Add($g.path) } } catch {} } } }
  # common folders on every drive that exists
  foreach ($drv in (Get-PSDrive -PSProvider FileSystem -ErrorAction SilentlyContinue)) { $r = $drv.Root.TrimEnd('\')
    foreach ($sub in 'Epic Games\Hob','Program Files\Epic Games\Hob','SteamLibrary\steamapps\common\Hob','Program Files (x86)\Steam\steamapps\common\Hob','GOG Games\Hob','Program Files (x86)\GOG Galaxy\Games\Hob') { $cands.Add("$r\$sub") } }
  $found = @()
  foreach ($c in $cands) {
    try { if ($c -and (Test-Path -LiteralPath "$c\HOB.exe") -and (Test-Path -LiteralPath "$c\plugins.cfg")) { $r = (Resolve-Path -LiteralPath $c).Path.TrimEnd('\'); if ($found -notcontains $r) { $found += $r } } } catch {}   # missing drive or folder: just skip it
  }
  if ($found.Count -le 1) { return $found | Select-Object -First 1 }
  Say 'Hob is installed in more than one place:' 'Yellow'
  for ($i = 0; $i -lt $found.Count; $i++) { Say "  $($i + 1)) $($found[$i])" }
  do { $a = Read-Host "Which one? Type a number (1-$($found.Count))" } while (-not ($a -match '^\d+$' -and [int]$a -ge 1 -and [int]$a -le $found.Count))
  return $found[[int]$a - 1]
}
if ($GameDir) { $Game = $GameDir; if (-not (Test-Path (Join-Path $Game 'HOB.exe'))) { Fail "No HOB.exe in $Game" } } else { $Game = Find-Hob }
if (-not $Game) {
  Say 'Could not find the Hob folder automatically. Please pick it (the folder that contains HOB.exe).' 'Yellow'
  Add-Type -AssemblyName System.Windows.Forms
  $dlg = New-Object System.Windows.Forms.FolderBrowserDialog; $dlg.Description = 'Select the Hob game folder (contains HOB.exe)'
  if ($dlg.ShowDialog() -ne 'OK') { Fail 'No folder chosen.' }
  $Game = $dlg.SelectedPath
  if (-not (Test-Path (Join-Path $Game 'HOB.exe'))) { Fail "No HOB.exe in $Game" }
}
Say "Game folder: $Game"
$Docs = Join-Path ([Environment]::GetFolderPath('MyDocuments')) 'My Games\Runic Games\HOB'
$Tools = Join-Path $Docs 'HobTools'
$StartMenu = Join-Path ([Environment]::GetFolderPath('Programs')) 'Hob Keybinds.lnk'
$exe = Join-Path $Game 'HOB.exe'; $bak = Join-Path $Game 'HOB.exe.original'
$cfg = Join-Path $Game 'plugins.cfg'; $cfgbak = Join-Path $Game 'plugins.cfg.bak'
$dll = Join-Path $Game 'Plugin_HobTools.dll'

