$Builds = @( @{ Name = 'Epic 1.17.3'; Patches = $patches }, @{ Name = 'Steam 1.17.2'; Patches = $patchesSteam } )

function Same($b, $o, $arr) { if ($o + $arr.Length -gt $b.Length) { return $false }; for ($i=0; $i -lt $arr.Length; $i++) { if ($b[$o+$i] -ne $arr[$i]) { return $false } }; return $true }
function Find-Build($b) {
  foreach ($bd in $Builds) { $ok = $true
    foreach ($p in $bd.Patches) { if (-not ((Same $b $p.Off $p.Old) -or (Same $b $p.Off $p.New))) { $ok = $false; break } }
    if ($ok) { return $bd } }
  return $null
}

function Set-ConsoleKey($from, $to) {
  # The game's console key is TILDA (the key left of 1) by default; HobTools moves it to B.
  $files = @(); $root = Join-Path $Docs 'PLAYER_CONTROLS.TXT'; if (Test-Path $root) { $files += $root }
  $saves = Join-Path $Docs 'SAVES'
  if (Test-Path $saves) { Get-ChildItem $saves -Directory | ForEach-Object { $f = Join-Path $_.FullName 'PLAYER_CONTROLS.TXT'; if (Test-Path $f) { $files += $f } } }
  $enc = [Text.Encoding]::GetEncoding(28591); $n = 0
  foreach ($f in $files) {
    $t = $enc.GetString([IO.File]::ReadAllBytes($f))
    if ($to -ne 'TILDA' -and $t -match "INPUT\d:$to\r?\n") { continue }   # key already used for something else - leave it
    $t2 = [regex]::Replace($t, "(\[CONSOLE\][^\[]*?INPUT0:)$from(\r?\n)", "`${1}$to`${2}")
    if ($t2 -ne $t) { [IO.File]::WriteAllBytes($f, $enc.GetBytes($t2)); $n++ }
  }
  return @{ Files = $files.Count; Changed = $n }
}

# ================= UNINSTALL =================
if ($Uninstall) {
  $n = 0
  if (Test-Path $bak) { Copy-Item $bak $exe -Force; Remove-Item $bak -Force; Say 'Restored the original HOB.exe'; $n++ }
  else {
    # no backup - undo the patches in place if they are present
    $b = [System.IO.File]::ReadAllBytes($exe); $undo = 0
    $bd = Find-Build $b; $plist = if ($bd) { $bd.Patches } else { @() }
    foreach ($p in $plist) { if (Same $b $p.Off $p.New) { for ($i=0; $i -lt $p.Old.Length; $i++) { $b[$p.Off+$i] = $p.Old[$i] }; $undo++ } }
    if ($undo) { [System.IO.File]::WriteAllBytes($exe, $b); Say "Removed $undo patch(es) from HOB.exe"; $n++ }
  }
  if (Test-Path $cfgbak) { Copy-Item $cfgbak $cfg -Force; Remove-Item $cfgbak -Force; Say 'Restored plugins.cfg'; $n++ }
  elseif (Test-Path $cfg) { $t = Get-Content $cfg -Raw; $t2 = ($t -split "`r?`n" | Where-Object { $_ -notmatch 'Plugin_HobTools' }) -join "`r`n"; if ($t2 -ne $t) { Set-Content $cfg $t2 -NoNewline; Say 'Removed the plugin line from plugins.cfg'; $n++ } }
  foreach ($f in $dll, (Join-Path $Game 'HobTools.log'), $StartMenu, (Join-Path $Docs 'HobTools.ini')) { if (Test-Path $f) { Remove-Item $f -Force; Say "Removed $(Split-Path $f -Leaf)"; $n++ } }
  if (Test-Path $Tools) { Remove-Item $Tools -Recurse -Force; Say 'Removed the HobTools folder in Documents'; $n++ }
  $r = Set-ConsoleKey 'B' 'TILDA'; if ($r.Changed) { Say 'Console key set back to the game default'; $n++ }
  # backups Hob Keybinds made of the controls files the first time it opened
  $ob = @(Join-Path $Docs 'PLAYER_CONTROLS.TXT.original')
  $sv = Join-Path $Docs 'SAVES'; if (Test-Path $sv) { Get-ChildItem $sv -Directory | ForEach-Object { $ob += (Join-Path $_.FullName 'PLAYER_CONTROLS.TXT.original') } }
  $k = 0; foreach ($f in $ob) { if (Test-Path $f) { Remove-Item $f -Force -ErrorAction SilentlyContinue; $k++ } }
  if ($k) { Say "Removed $k controls backup file(s) made by Hob Keybinds"; $n++ }
  Say ''
  if ($n) { Say 'HobTools has been removed. Your key bindings and saves were not touched.' 'Green' } else { Say 'HobTools was not installed here.' 'Yellow' }
  Say 'Other key changes you made with Hob Keybinds stay; reset them in the game under Options > Controls if you like.'
  exit 0
}

# ================= INSTALL =================
foreach ($f in 'Plugin_HobTools.dll','Hob Keybinds.exe','README.txt') { if (-not (Test-Path (Join-Path $Here $f))) { Fail "Missing file: $f (extract the whole zip before installing)" } }

# Files extracted from a downloaded zip carry Windows' "from the internet" mark; clear it so Hob Keybinds opens without a warning.
Get-ChildItem $Here -File -Recurse -ErrorAction SilentlyContinue | Unblock-File -ErrorAction SilentlyContinue

# 1. HOB.exe patches (unlock the developer console, readable help)
$b = [System.IO.File]::ReadAllBytes($exe); $todo = 0
$bd = Find-Build $b
if (-not $bd) { Fail 'This HOB.exe is not a version HobTools supports (Epic 1.17.3 or Steam 1.17.2).' }
Say "Game version: $($bd.Name)"
$patches = $bd.Patches
foreach ($p in $patches) { if (Same $b $p.Off $p.Old) { $todo++ } }
if ($todo) {
  if (-not (Test-Path $bak)) { Copy-Item $exe $bak; Say 'Backup saved as HOB.exe.original' }
  foreach ($p in $patches) { if (Same $b $p.Off $p.Old) { for ($i=0; $i -lt $p.New.Length; $i++) { $b[$p.Off+$i] = $p.New[$i] } } }
  [System.IO.File]::WriteAllBytes($exe, $b); Say "HOB.exe: developer console unlocked ($todo patches)"
} else { Say 'HOB.exe: already patched' }

# 2. plugins.cfg
$t = Get-Content $cfg -Raw
if ($t -notmatch 'Plugin=Plugin_HobTools') {
  if (-not (Test-Path $cfgbak)) { Copy-Item $cfg $cfgbak }
  if (-not $t.EndsWith("`n")) { $t += "`r`n" }
  Set-Content $cfg ($t + " Plugin=Plugin_HobTools`r`n") -NoNewline
  Say 'plugins.cfg: plugin added'
} else { Say 'plugins.cfg: plugin already listed' }

# 3. the plugin
Copy-Item (Join-Path $Here 'Plugin_HobTools.dll') $dll -Force; Say 'Plugin_HobTools.dll installed'

# 4. Keybinds app, README, default settings in Documents
New-Item -ItemType Directory -Force $Tools | Out-Null
Copy-Item (Join-Path $Here 'Hob Keybinds.exe') (Join-Path $Tools 'Hob Keybinds.exe') -Force
Copy-Item (Join-Path $Here 'README.txt') (Join-Path $Tools 'HobTools_README.txt') -Force
$ini = Join-Path $Docs 'HobTools.ini'
if (-not (Test-Path $ini)) { Set-Content $ini "; HobTools mod keys - change them with Hob Keybinds.exe`r`n[Keys]`r`nNOCLIP=F6`r`nFREECAM=F7`r`nTELEPORT=F8`r`nFOLLOW=F9`r`nSPEEDUP=PAGEUP`r`nSPEEDDOWN=PAGEDOWN`r`n" -NoNewline }
Get-ChildItem $Tools -File | Unblock-File -ErrorAction SilentlyContinue; Unblock-File $dll -ErrorAction SilentlyContinue
try { $ws = New-Object -ComObject WScript.Shell; $sc = $ws.CreateShortcut($StartMenu); $sc.TargetPath = (Join-Path $Tools 'Hob Keybinds.exe'); $sc.WorkingDirectory = $Tools; $sc.Description = 'Change Hob and HobTools key bindings'; $sc.Save(); Say 'Start menu shortcut: Hob Keybinds' } catch {}
Say "Hob Keybinds + README: $Tools"
$r = Set-ConsoleKey 'TILDA' 'B'
if ($r.Files -eq 0) { $ConsoleKey = 'the key left of 1'; Say 'Console key: the game has no controls file yet - start Hob once, then run this installer again to put the console on B.' 'Yellow' }
elseif ($r.Changed) { $ConsoleKey = 'B'; Say 'Console key set to B' }
else { $ConsoleKey = $null; Say 'Console key: left as you had it' }
Say ''
Say 'HobTools is installed.' 'Green'
if ($ConsoleKey) { Say "  In game:  $ConsoleKey opens the developer console (type help)." } else { Say '  In game:  your console key opens the developer console (type help).' }
Say '  F6 noclip, F7 free camera, F8 teleport Hob to the camera.'
Say '  Change any key with "Hob Keybinds" (Start menu). Full details in the README.'
Say '  To remove the mod, run Uninstall HobTools.bat.'
